<?php
session_start();
require_once __DIR__ . '/db.php';
$mode = $_GET['mode'] ?? 'online';
if (!in_array($mode, ['online', 'race', 'practice'], true)) $mode = 'online';
$rows = []; $error = '';
try {
    $pdo = database();
    if ($mode === 'online') {
        $rows = $pdo->query("SELECT u.username, u.avatar, s.wins, s.losses, s.games_played, COALESCE(MAX(CASE WHEN m.player1_id = u.id THEN m.player1_wpm ELSE m.player2_wpm END), 0) AS wpm FROM online_stats s JOIN users u ON u.id = s.user_id LEFT JOIN online_matches m ON m.status = 'completed' AND (m.player1_id = u.id OR m.player2_id = u.id) WHERE s.games_played > 0 GROUP BY u.id, u.username, u.avatar, s.wins, s.losses, s.games_played ORDER BY wpm DESC, s.wins DESC, u.username ASC LIMIT 20")->fetchAll();
    } else {
        $stmt = $pdo->prepare('SELECT u.username, u.avatar, s.difficulty, s.wpm, s.accuracy, s.words_correct, s.elapsed_ms, s.won, s.created_at FROM scores s JOIN users u ON u.id = s.user_id WHERE s.mode = ? ORDER BY s.wpm DESC, s.won DESC, s.accuracy DESC, s.elapsed_ms ASC, s.created_at ASC LIMIT 500');
        $stmt->execute([$mode]); $seen = [];
        foreach ($stmt->fetchAll() as $row) {
            if (isset($seen[$row['username']])) continue;
            $seen[$row['username']] = true; $rows[] = $row;
            if (count($rows) >= 20) break;
        }
    }
} catch (Throwable $e) { $error = 'Leaderboard is not ready yet. Import the latest database.sql file in phpMyAdmin, then reload this page.'; }
function leaderboardEsc($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
?>
