?><div class="leader-empty"><span class="empty-trophy">✦</span><b>No scores yet.</b><span><?= $mode === 'online' ? 'Finish your first online duel and your record will show here.' : 'Sign in, play a round, and your result will appear here.' ?></span><a class="button button-primary" href="<?= $mode === 'online' ? 'online.php' : 'auth.php?form=register' ?>"><?= $mode === 'online' ? 'Find an opponent' : 'Create account' ?> <span>→</span></a></div><?php else: ?><?php foreach ($rows as $index => $row): ?><div class="leader-row <?= $mode === 'online' ? 'online-leader-row' : '' ?>"><span class="leader-rank"><i><?= str_pad((string)($index + 1), 2, '0', STR_PAD_LEFT) ?></i><span class="leader-avatar"><?= leaderboardEsc($row['avatar'] ?? '⌨️') ?></span><b><?= leaderboardEsc($row['username']) ?></b></span><strong class="leader-wpm"><?= (int)$row['wpm'] ?><small> WPM</small></strong><?php if ($mode === 'online'): ?><span><?= (int)$row['wins'] ?></span><span><?= (int)$row['losses'] ?></span><span><?= (int)$row['games_played'] ?></span><?php else: ?><span class="leader-level"><?= leaderboardEsc(ucfirst($row['difficulty'])) ?><?= $mode === 'race' && $row['won'] ? ' · WIN' : '' ?></span><span><?= (int)$row['words_correct'] ?>/10</span><span><?= (int)$row['accuracy'] ?>%</span><?php endif; ?></div><?php endforeach; ?><?php endif; ?></section><a class="back-link" href="index.php#modes">← Back to lobby</a></main><footer class="wrap footer"><a class="brand" href="index.php"><span class="brand-mark">K</span> keydash<span class="brand-dot">.</span></a><span>© <?= date('Y') ?> Keydash</span></footer></body></html>
